    seen = set()
    parts = []
    height = len(grid)
    width = len(grid[0])
    for r in range(height):
        for c in range(width):
            if grid[r][c] != 9 or (r, c) in seen:
                continue
            part = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                part.append((rr, cc))
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr = rr + dr
                    nc = cc + dc
                    if 0 <= nr < height and 0 <= nc < width:
                        if grid[nr][nc] == 9 and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            parts.append(part)
    return parts


def _glyphs_match(grid):
    small = None
    large = None
    for part in _nine_components(grid):
        rows = [cell[0] for cell in part]
        cols = [cell[1] for cell in part]
        h = max(rows) - min(rows) + 1
        w = max(cols) - min(cols) + 1
        if h == 3 and w == 3:
            small = part
        elif h == 6 and w == 6:
            large = part
    if small is None or large is None:
        return False
    small_set = set(small)
    large_set = set(large)
    sr0 = min([cell[0] for cell in small])
    sc0 = min([cell[1] for cell in small])
    lr0 = min([cell[0] for cell in large])
    lc0 = min([cell[1] for cell in large])
    for rr in range(3):
        for cc in range(3):
            small_on = (sr0 + rr, sc0 + cc) in small_set
            large_on = True
            for dy in range(2):
                for dx in range(2):
                    if (lr0 + 2 * rr + dy, lc0 + 2 * cc + dx) not in large_set:
                        large_on = False
            if small_on != large_on:
                return False
    return True


def _reflect_lower_panel(grid):
    # The display is the ten-cell-wide 5/9 panel bounded by color 4.
    # Reflecting every qualifying row also handles symmetric rows unchanged.
    for row in grid:
        if len(row) > 11 and row[0] == 4 and row[11] == 4:
            panel_row = row[1:11]
            valid = True
            for value in panel_row:
                if value not in (5, 9):
                    valid = False
            if valid:
                for c in range(10):
                    row[1 + c] = panel_row[9 - c]


