        for c in range(nc0, nc0 + size):
            destination.append(grid[r][c])
    switch_contact = False
    glyph_contact = False
    for value in destination:
        if value in (0, 1):
            switch_contact = True
        if value == 9:
            glyph_contact = True
    move_kind = 0
    if switch_contact:
        move_kind = 2
        for value in destination:
            if value not in (0, 1, 3, 5):
