            move_kind = _move_target(nxt, -size, 0)
        elif aid == 2:
            move_kind = _move_target(nxt, size, 0)
        elif aid == 3:
            move_kind = _move_target(nxt, 0, -size)
        elif aid == 4:
            move_kind = _move_target(nxt, 0, size)
    if move_kind == 1:
        _advance_bar(nxt)
    elif move_kind == 2:
        _reflect_lower_panel(nxt)
